import 'package:geolocator/geolocator.dart';
import 'package:supabase_flutter/supabase_flutter.dart';

class OpenBackend {
  OpenBackend._(); static final instance=OpenBackend._(); final SupabaseClient client=Supabase.instance.client;
  String? get userId=>client.auth.currentUser?.id; bool get isAuthenticated=>userId!=null;
  Future<AuthResponse> registerEmail(String email,String password)=>client.auth.signUp(email:email.trim(),password:password);
  Future<AuthResponse> loginEmail(String email,String password)=>client.auth.signInWithPassword(email:email.trim(),password:password);
  Future<void> sendPhoneOtp(String phone)async{}
  String _mockPhoneEmail(String phone){final d=phone.replaceAll(RegExp(r'\D'),'');return 'phone_$d@mock.open.local';}
  String _mockPhonePassword(String phone){final d=phone.replaceAll(RegExp(r'\D'),'');return 'OpenMock!$d#123456';}
  Future<AuthResponse> verifyPhoneOtp(String phone,String token)async{if(token.trim()!='123456'){throw const AuthException('Mock kod hatalı');}final email=_mockPhoneEmail(phone),password=_mockPhonePassword(phone);try{return await client.auth.signInWithPassword(email:email,password:password);}on AuthException catch(e){final m=e.message.toLowerCase();if(!m.contains('invalid login credentials')&&!m.contains('invalid credentials')){rethrow;}}final r=await client.functions.invoke('mock-phone-auth',body:{'phone':phone.trim(),'token':token.trim()});if(r.status<200||r.status>=300){throw AuthException('Mock telefon hesabı oluşturulamadı: ${r.data}');}return client.auth.signInWithPassword(email:email,password:password);}
  Future<AuthResponse> startMockPhoneSession()=>client.auth.signInAnonymously();
  Future<bool> hasCompletedProfile()async{final id=userId;if(id==null){return false;}final r=await client.from('profiles').select('profile_complete').eq('id',id).maybeSingle();return r!=null&&r['profile_complete']==true;}
  Future<bool> hasProfile()async{final id=userId;if(id==null){return false;}return await client.from('profiles').select('id').eq('id',id).maybeSingle()!=null;}
  Future<void> signOut()=>client.auth.signOut();
  Future<void> saveProfile(String name,String city,String gender,{String country='',String district=''})async{final n=name.trim(),c=city.trim();if(n.isEmpty||c.isEmpty){throw ArgumentError('Ad ve konum zorunlu');}await client.from('profiles').upsert({'id':_uid(),'display_name':n,'city':c,'country':country.trim(),'district':district.trim(),'gender':gender});}
  Future<List<Map<String,dynamic>>> saveLockQuestions(List<String> questions)async{final id=_uid(),q=questions.map((e)=>e.trim()).toList();if(q.length!=3||q.any((e)=>e.isEmpty)){throw ArgumentError('3 geçerli soru seçilmeli');}final rows=await client.from('profile_questions').upsert([for(var i=0;i<q.length;i++){'profile_id':id,'question':q[i],'position':i+1}],onConflict:'profile_id,position').select('id,question,position').order('position');await client.from('profiles').update({'profile_complete':true}).eq('id',id);return List<Map<String,dynamic>>.from(rows);}
  int _age(dynamic v){if(v==null){return -1;}final d=DateTime.tryParse(v.toString());if(d==null){return -1;}final n=DateTime.now();var a=n.year-d.year;if(n.month<d.month||(n.month==d.month&&n.day<d.day)){a--;}return a;}
  bool _genderMatches(String pref,dynamic gender){final p=pref.trim().toLowerCase(),g=(gender??'').toString().trim().toLowerCase();if(p.isEmpty||p=='herkes'){return true;}if(p.startsWith('kad')){return g.startsWith('kad')||g=='female'||g=='woman';}if(p.startsWith('erk')){return g.startsWith('erk')||g=='male'||g=='man';}return true;}
  Future<Position?> _refreshPosition()async{try{if(!await Geolocator.isLocationServiceEnabled())return null;var permission=await Geolocator.checkPermission();if(permission==LocationPermission.denied)permission=await Geolocator.requestPermission();if(permission==LocationPermission.denied||permission==LocationPermission.deniedForever)return null;final pos=await Geolocator.getCurrentPosition(locationSettings:const LocationSettings(accuracy:LocationAccuracy.medium,timeLimit:Duration(seconds:10)));await client.from('profiles').update({'latitude':pos.latitude,'longitude':pos.longitude}).eq('id',_uid());return pos;}catch(_){return null;}}
  Future<List<Map<String,dynamic>>> discover()async{final id=_uid();final sr=await client.from('user_settings').select('looking_for,min_age,max_age,max_distance_km').eq('user_id',id).limit(1);final s=sr.isEmpty?<String,dynamic>{}:Map<String,dynamic>.from(sr.first);final pref=(s['looking_for']??'Herkes').toString(),min=(s['min_age'] as num?)?.toInt()??18,max=(s['max_age'] as num?)?.toInt()??80,maxKm=(s['max_distance_km'] as num?)?.toDouble()??50;var pos=await _refreshPosition();if(pos==null){final me=await client.from('profiles').select('latitude,longitude').eq('id',id).maybeSingle();final lat=(me?['latitude'] as num?)?.toDouble(),lng=(me?['longitude'] as num?)?.toDouble();if(lat!=null&&lng!=null)pos=Position(longitude:lng,latitude:lat,timestamp:DateTime.now(),accuracy:0,altitude:0,altitudeAccuracy:0,heading:0,headingAccuracy:0,speed:0,speedAccuracy:0);}
    final data=await client.from('profiles').select('id,display_name,birth_date,bio,city,country,district,gender,avatar_url,gallery_urls,interests,is_online,is_verified,account_paused,latitude,longitude,profile_questions(id,question,position)').eq('profile_complete',true).neq('id',id).limit(100);
    final out=<Map<String,dynamic>>[];for(final raw in List<Map<String,dynamic>>.from(data)){final p=Map<String,dynamic>.from(raw);if(p['account_paused']==true||!_genderMatches(pref,p['gender']))continue;final a=_age(p['birth_date']);if(a>=0&&(a<min||a>max))continue;final lat=(p['latitude'] as num?)?.toDouble(),lng=(p['longitude'] as num?)?.toDouble();if(pos!=null){if(lat==null||lng==null)continue;final km=Geolocator.distanceBetween(pos.latitude,pos.longitude,lat,lng)/1000;if(km>maxKm)continue;p['distance_km']=km;}out.add(p);if(out.length>=30)break;}return out;}
  Future<void> sendKey(String receiverId,String questionId,String answer)async{final a=answer.trim();if(a.isEmpty){throw ArgumentError('Cevap boş olamaz');}await client.from('key_requests').insert({'sender_id':_uid(),'receiver_id':receiverId,'question_id':questionId,'answer':a});}
  Future<List<Map<String,dynamic>>> incomingKeys()async=>List<Map<String,dynamic>>.from(await client.from('key_requests').select('id,sender_id,answer,status,created_at,profiles!key_requests_sender_id_fkey(display_name,avatar_url),profile_questions(question)').eq('receiver_id',_uid()).order('created_at',ascending:false));
  Future<void> rejectKey(String requestId)async{final me=_uid();await client.from('key_requests').update({'status':'rejected','responded_at':DateTime.now().toUtc().toIso8601String()}).eq('id',requestId).eq('receiver_id',me).eq('status','pending');}
  Future<String> acceptKey(String requestId)async{final me=_uid(),request=await client.from('key_requests').select('sender_id,status').eq('id',requestId).eq('receiver_id',me).single();final sender=request['sender_id'].toString();final existing=await client.from('matches').select('id').or('and(user_a.eq.$sender,user_b.eq.$me),and(user_a.eq.$me,user_b.eq.$sender)').eq('active',true).maybeSingle();if(request['status']=='pending'){await client.from('key_requests').update({'status':'accepted','responded_at':DateTime.now().toUtc().toIso8601String()}).eq('id',requestId).eq('receiver_id',me).eq('status','pending');}else if(request['status']!='accepted'){throw StateError('Anahtar kabul edilebilir durumda değil');}if(existing!=null){return existing['id'] as String;}try{return (await client.from('matches').insert({'user_a':sender,'user_b':me,'key_request_id':requestId}).select('id').single())['id'] as String;}on PostgrestException catch(e){if(e.code!='23505'){rethrow;}return (await client.from('matches').select('id').or('and(user_a.eq.$sender,user_b.eq.$me),and(user_a.eq.$me,user_b.eq.$sender)').eq('active',true).single())['id'] as String;}}
  Future<List<Map<String,dynamic>>> activeMatches()async{final me=_uid();return List<Map<String,dynamic>>.from(await client.from('matches').select('id,user_a,user_b,created_at').or('user_a.eq.$me,user_b.eq.$me').eq('active',true).order('created_at',ascending:false));}
  Stream<List<Map<String,dynamic>>> messageStream(String matchId)=>client.from('messages').stream(primaryKey:['id']).eq('match_id',matchId).order('created_at').map((r)=>List<Map<String,dynamic>>.from(r));
  Future<void> sendMessage(String matchId,String text)async{final b=text.trim();if(b.isEmpty){throw ArgumentError('Mesaj boş olamaz');}await client.from('messages').insert({'match_id':matchId,'sender_id':_uid(),'body':b});}
  String _uid(){final id=userId;if(id==null){throw StateError('Supabase oturumu gerekli');}return id;}
}
